const foundationTransactionLimits: TransactionStoreOptions = Object.freeze({ maxLineBytes: 262_144, maxFileBytes: 1_048_576, maxTransactionBytes: 4_194_304 });
const effectiveScholarlyLimits = Object.freeze({ maxSourceRecordCanonicalBytes: 262_143, maxRequestRecordCanonicalBytes: 262_143, maxClaimRecordCanonicalBytes: 262_143, maxEvidenceRecordCanonicalBytes: 262_143, maxVerificationRecordCanonicalBytes: 262_143, maxCalculationRecordCanonicalBytes: 262_143, maxCanonicalEvidenceSetBytes: 1_048_576 });
